package org.apache.commons.lang3.time;

import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Lang_18_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        FastDateFormat format = FastDateFormat.getInstance("yy-MM-dd");
        try {
            format.parsePattern();
            fail("Expected IllegalArgumentException for two-digit year pattern");
        } catch (IllegalArgumentException e) {
            assertEquals("Illegal pattern component: yy", e.getMessage());
        }
    }
}

